    "content": "@tailwind base;
@tailwind components;
@tailwind utilities;

/* Claude Theme from tweakcn */
@layer base {
  :root {
    --background: 30 25% 98%;
    --foreground: 30 10% 10%;
    --card: 30 20% 96%;
    --card-foreground: 30 10% 10%;
    --popover: 30 25% 98%;
    --popover-foreground: 30 10% 10%;
    --primary: 24 75% 50%;
    --primary-foreground: 0 0% 100%;
    --secondary: 30 15% 92%;
    --secondary-foreground: 30 10% 20%;
    --muted: 30 15% 92%;
    --muted-foreground: 30 10% 45%;
    --accent: 24 70% 95%;
    --accent-foreground: 24 75% 35%;
    --destructive: 0 84% 60%;
    --destructive-foreground: 0 0% 100%;
    --border: 30 15% 88%;
    --input: 30 15% 88%;
    --ring: 24 75% 50%;
    --radius: 0.625rem;
  }

  .dark {
    --background: 30 10% 8%;
    --foreground: 30 10% 95%;
    --card: 30 10% 12%;
    --card-foreground: 30 10% 95%;
    --popover: 30 10% 8%;
    --popover-foreground: 30 10% 95%;
    --primary: 24 80% 55%;
    --primary-foreground: 0 0% 100%;
    --secondary: 30 10% 18%;
    --secondary-foreground: 30 10% 90%;
    --muted: 30 10% 18%;
    --muted-foreground: 30 10% 60%;
    --accent: 24 50% 20%;
    --accent-foreground: 24 80% 70%;
    --destructive: 0 72% 50%;
    --destructive-foreground: 0 0% 100%;
    --border: 30 10% 22%;
    --input: 30 10% 22%;
    --ring: 24 80% 55%;
  }
}

@layer base {
  * {
    @apply border-border;
    user-select: none;
  }
  html, body {
    @apply bg-background text-foreground;
    overflow: hidden;
  }
  body {
    font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  }
  #root {
    height: 100vh;
    width: 100vw;
  }
  /* Allow text selection in input fields */
  input[type="text"],
  input[type="password"],
  input[type="email"],
  input[type="number"],
  input[type="search"],
  input[type="url"],
  input[type="tel"],
  textarea,
  [contenteditable="true"] {
    user-select: text;
  }
}

/* Custom scrollbar */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: hsl(var(--muted));
  border-radius: 4px;
}

::-webkit-scrollbar-thumb {
  background: hsl(var(--muted-foreground) / 0.3);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: hsl(var(--muted-foreground) / 0.5);
}

/* Drag and drop zone styles */
.dropzone-active {
  @apply border-primary bg-accent;
}

/* Remove focus outline on mouse interaction, keep it for keyboard navigation */
button:focus:not(:focus-visible) {
  outline: none;
}

*:focus:not(:focus-visible) {
  outline: none;
}

/* Cursor styles for interactive elements */
input[type="radio"],
input[type="checkbox"] {
  cursor: pointer;
}

input[type="radio"]:disabled,
input[type="checkbox"]:disabled {
  cursor: not-allowed;
}

a {
  cursor: pointer;
}

summary {
  cursor: pointer;
}
",
